def detail_sections(title, text):
    """Split inside the log, keeping every comment's HTML and fences balanced."""
    chunks = []
    while text:
        end = min(len(text), 48000)
        if end < len(text):
            end = text.rfind('\n', 0, end) + 1 or end
        chunks.append(text[:end])
        text = text[end:]
    return ['<details><summary>{}{}</summary>\n\n{}\n\n</details>'.format(
        html.escape(title), ' (part {})'.format(i + 1) if len(chunks) > 1 else '',
        fenced(chunk)) for i, chunk in enumerate(chunks or ['None.'])]


def diagnostic_sections():
    warnings, errors = [], []
    candidate, baseline = {}, set()
    comparable = set()
    paths = []
    for path, name, output, complete in captured_logs():
        paths.append(path)
        is_baseline = name.startswith('baseline-') or path.startswith('_baseline/')
        # Only compare equivalent completed commands; failed/missing steps are unknown.
        if name.startswith('baseline-'):
            complete = complete or (read_text(path + '.exit').strip() == '0' or
                        (name.endswith('.log') and os.path.isfile(name[:-4] + '-seconds.txt')))
            if complete:
                comparable.add(name[len('baseline-'):])
        lines = ANSI.sub('', output).splitlines()
        for i, line in enumerate(lines):
            entry = '{}:{}: {}'.format(path, i + 1, line)
            # Include source/caret/continuation lines with the diagnostic.
            context = []
            for following in lines[i + 1:i + 7]:
                if not following.strip() or not following[:1].isspace() or WARNING_LINE.search(following) or ERROR_LINE.search(following):
                    break
                context.append(following)
            if context:
                entry += '\n' + '\n'.join(context)
            if WARNING_LINE.search(line):
                warnings.append(entry)
                key = warning_key(line)
                if is_baseline:
                    baseline.add(key)
                elif name.startswith('candidate-'):
                    candidate[(name[len('candidate-'):], key)] = entry
            if ERROR_LINE.search(line) and not WARNING_LINE.search(line):
                errors.append(entry)

    selection = read_kv('ci-selection.txt')
    ref = first(selection, 'baseline_selector', 'main')
    new = [entry for (step, key), entry in candidate.items() if step in comparable and key not in baseline]
    unknown = [entry for (step, key), entry in candidate.items() if step not in comparable]
    note = 'Compared equivalent completed build steps against {}. Source line/column shifts are ignored.'.format(ref)
    if ref != 'main':
        note += ' This run selected a baseline other than main.'
    if not comparable:
        note = 'Comparison unavailable: no matching completed baseline build logs. Warnings cannot be classified as new.'
    elif unknown:
        note += '\n{} distinct candidate warnings could not be compared because their baseline step did not complete.'.format(len(unknown))
    sections = detail_sections('New warnings vs {} ({})'.format(ref, len(new) if comparable else 'unknown'),
  done
}

manifest_valid() {
  local root="$1" platform="$2" sha="$3"
  cache_tree_valid "$(baseline_path "$root" "$platform")/$sha" "$platform" "$sha"
}

prepare_baseline_stage() {
  local root platform sha parent target
  root="$1"; platform="$2"; sha="$3"
  [[ "$sha" =~ ^[0-9a-f]{40}$ ]] || die 'baseline commit must be a full SHA'
  parent="$(baseline_path "$root" "$platform")"
  mkdir -p "$parent"
  target="$parent/$sha"
  # Installed binaries and libraries can embed this absolute path. Keep it fixed
  # from the build through every later cache hit.
  rm -rf "$target"
  mkdir -p "$target/gkeyll"
  printf '%s' "$target"
}

publish_baseline() {
  local root="$1" platform="$2" sha="$3" stage="$4" parent target
  parent="$(baseline_path "$root" "$platform")"
  target="$parent/$sha"
  [[ -d "$stage" ]] || die "baseline directory is missing: $stage"
  [[ "$stage" == "$target" ]] || die "baseline must be built at its final path: $target"
  cache_tree_valid "$target" "$platform" "$sha" || die "baseline cache is incomplete or invalid: $target"
  find "$parent" -mindepth 1 -maxdepth 1 -type d ! -name "$sha" -exec rm -rf {} +
  printf '%s' "$target"
}

prepare_candidate() {
  local root="$1" platform="$2" sha="$3" source="$4" baseline_sha="$5" parent target head
  [[ "$sha" =~ ^[0-9a-f]{40}$ && "$baseline_sha" =~ ^[0-9a-f]{40}$ ]] || die 'candidate and baseline commits must be full SHAs'
  [[ -d "$source/.git" ]] || die "candidate checkout is missing: $source"
  head="$(git -C "$source" rev-parse HEAD 2>/dev/null || true)"
  [[ "$head" == "$sha" ]] || die "candidate checkout does not match $sha"
  parent="$(candidate_path "$root" "$platform")"
  target="$parent/$sha"
  rm -rf "$parent"
  mkdir -p "$target/gkeyll"
  # Copy source before building; installed libraries must stay at this path.
  cp -a "$source/." "$target/gkeyll/"
  [[ "$(git -C "$target/gkeyll" rev-parse HEAD 2>/dev/null || true)" == "$sha" ]] || die "candidate copy does not match $sha"
  rm -f "$target/candidate-manifest.txt"
  printf 'candidate_commit=%s\nbaseline_commit=%s\nresult=building\nbuild_tag=%s\n' "$sha" "$baseline_sha" "${BUILD_TAG:-manual}" > "$target/candidate-manifest.txt"
  printf '%s' "$target"
}

finalize_candidate() {
  local root="$1" platform="$2" sha="$3" baseline_sha="$4" result="$5" stage="$6" workspace="$7" target file destination
  [[ "$sha" =~ ^[0-9a-f]{40}$ && "$baseline_sha" =~ ^[0-9a-f]{40}$ ]] || die 'candidate and baseline commits must be full SHAs'
  target="$(candidate_path "$root" "$platform")/$sha"
  [[ -d "$target/gkeyll/.git" ]] || die "candidate checkout is missing: $target/gkeyll"
  [[ -d "$workspace" ]] || die "Jenkins workspace is missing: $workspace"
  [[ "$(git -C "$target/gkeyll" rev-parse HEAD 2>/dev/null || true)" == "$sha" ]] || die "candidate checkout does not match $sha"
  for file in "$workspace"/ci-*.txt "$workspace"/*-unit-results.txt "$workspace"/*-seconds.txt "$workspace"/candidate-*.log "$workspace"/slurm-*.out "$workspace"/ci-report.md; do
    [[ -f "$file" && ! -L "$file" ]] || continue
    destination="$target/$(basename "$file")"
EOF

